use crate::domains::rust_perf::PerfRule;

/// Data table, not logic — grows with distillation batches.
#[allow(clippy::too_many_lines)]
pub(super) fn entries() -> Vec<PerfRule> {
    vec![
        // ── complexity (serving/drafting): prune the speculative work set
        // by PATH-LOCAL grammar admissibility BEFORE paying the verify
        // forward — row-locality is what makes the prune exact ────────
        // Source: engine/grammar.py (the window/visit DFS + mask) and
        // commit 98fb8f9 (the exactness law; the CUDA twin docstring).
        PerfRule {
            rule_id: "grammar-window-draft-prune-path-local-mask".to_string(),
            name: "when a reply carries a grammar (structured output), walk the drafted verify tree depth-first BEFORE the verify forward — the matcher accepting each row's token on the way down and rolling it back on the way up — and DROP every draft no accepted path can hold (a token the grammar rejects, a stop token, and every row under either), then fill each kept row's allowed-token bitmask from its own path and set the rest to -inf before sampling: the work set the forward is paid for is exactly the rows an accepted path could use".to_string(),
            category: "complexity".to_string(),
            buggy_code: "pub struct DraftWindow {\n    tokens: Vec<u32>,\n    parents: Vec<i32>, // parents[0] = -1: row 0 is the pending token\n}\n\n// The verify forward computes EVERY drafted row — including rows no\n// accepted path can hold (the subtree under a grammar-rejected token, a\n// stop token's rows) — and only afterwards do the logits get masked.\n// The forward is paid for rows that could never be chosen.\npub fn verify_all_rows(\n    logits: &mut [Vec<f32>],\n    window: &DraftWindow,\n    forward: impl Fn(usize, &mut Vec<f32>), // cost per row, paid up front\n    allowed: impl Fn(usize) -> &[bool],     // per-row mask, computed late\n) {\n    for r in 0..window.tokens.len() {\n        forward(r, &mut logits[r]); // every row, admissible or not\n    }\n    for (r, row) in logits.iter_mut().enumerate() {\n        for (t, v) in row.iter_mut().enumerate() {\n            if !allowed(r).get(t).copied().unwrap_or(false) {\n                *v = f32::NEG_INFINITY; // masking cannot refund the forward\n            }\n        }\n    }\n}".to_string(),
            fixed_code: "// A stand-in for the incremental matcher: accept_token walks its\n// path down, rollback walks it back up, is_terminated reports a stop.\nstruct GrammarMatcher {\n    live: Vec<u32>,\n    stop: bool,\n}\n\nimpl GrammarMatcher {\n    fn accept_token(&mut self, tok: u32) -> bool {\n        if self.stop {\n            return false; // grammar-rejected under the current path\n        }\n        self.live.push(tok);\n        true\n    }\n    fn is_terminated(&self) -> bool {\n        self.stop // a stop token ends the reply\n    }\n    fn rollback(&mut self, n: usize) {\n        let keep = self.live.len() - n;\n        self.live.truncate(keep);\n    }\n    fn allows(&self, _row: usize, _tok: usize) -> bool {\n        true // the row's own path's bitmask, filled by the matcher\n    }\n}\n\npub struct DraftWindow {\n    tokens: Vec<u32>,\n    parents: Vec<i32>,\n}\n\n// The DFS prune runs BEFORE the forward: the matcher accepts a row's\n// token on the way down and rolls it back on the way up. A token the\n// grammar rejects, a stop token, and the rows under either are dropped —\n// the parent's masked row cannot choose the first, and the reply ends at\n// the second, so no accepted path holds them. Rows no active grammar\n// path reaches are kept (nothing constrains them).\npub fn kept_rows(window: &DraftWindow, m: &mut GrammarMatcher) -> Vec<usize> {\n    let n = window.tokens.len();\n    let mut children: Vec<Vec<usize>> = vec![Vec::new(); n];\n    for (r, &p) in window.parents.iter().enumerate().skip(1) {\n        children[p as usize].push(r);\n    }\n    let mut kept = Vec::new();\n    fn visit(\n        m: &mut GrammarMatcher,\n        w: &DraftWindow,\n        kept: &mut Vec<usize>,\n        children: &[Vec<usize>],\n        r: usize,\n        active: bool,\n    ) {\n        if active {\n            kept.push(r); // this row's path is admissible: it gets masked\n        }\n        for &c in &children[r] {\n            if !active {\n                kept.push(c); // no grammar path reaches it: unconstrained\n                visit(m, w, kept, children, c, false);\n            } else if m.accept_token(w.tokens[c]) {\n                // rejected: the parent's masked row could never choose it\n                if !m.is_terminated() {\n                    // a stop token ends the reply — nothing verified after\n                    visit(m, w, kept, children, c, true);\n                }\n                m.rollback(1);\n            }\n        }\n    }\n    visit(m, window, &mut kept, &children, 0, true);\n    kept\n}\n\n// Forward + -inf mask the KEPT rows only; each row's mask is its own\n// path's, so the dropped rows were exactly the rows no accepted path\n// could use — the prune is exact, not approximate.\npub fn verify_kept(\n    logits: &mut [Vec<f32>],\n    kept: &[usize],\n    m: &GrammarMatcher,\n    forward: impl Fn(usize, &mut Vec<f32>),\n) {\n    for &r in kept {\n        forward(r, &mut logits[r]);\n        for (t, v) in logits[r].iter_mut().enumerate() {\n            if !m.allows(r, t) {\n                *v = f32::NEG_INFINITY;\n            }\n        }\n    }\n}".to_string(),
            context_notes: Some("NotBenchable decision-content (the win is rows-not-paid-for inside a serving stack's verify forward — a Rust microbench of a DFS would measure the wrong thing; the Batch-182 prompt-lookup annotation class). SOURCE (TensorFold v0.6.0 @ c4646171, Apache-2.0 — license flipped MIT→Apache-2.0 at 0.6.0; provenance: TensorFold v0.6.0 @ c4646171, Apache-2.0 (license flipped MIT→Apache-2.0 at 0.6.0), src/tensorfold/engine/grammar.py, verbatim): 'The rows an accepted path can use (row 0 the pending token, parents first), each constrained row's bits.' (:273, the window doc); the DFS — 'def visit(r: int, active: bool) -> None:      # the matcher has taken row r's path (when active)' (:297) with 'elif m.accept_token(tokens[c]):       # rejected: the parent's masked row could never choose it' (:305) and 'if not m.is_terminated():         # a stop token ends the reply, nothing is verified after it' + 'm.rollback(1)' (:306-308); the mask — 'def mask(self, logits, window: Window | None = None, offset: int = 0): \"\"\"``logits`` (columns from token ``offset``), constrained rows' other tokens -inf: torch in place, MLX new.\"\"\"' (:321-323). THE EXACTNESS LAW (commit 98fb8f9, diff to src/tensorfold/cuda/grammar.py — the CUDA twin since consolidated into engine/grammar.py by 1da4b7e; the sentence is NOT in the tree at the pin, commit-diff-only): 'A row's logits do not depend on the other rows, and its mask depends only on its path, so a drafted row and the serial step with the same path choose the same token, greedy or keyed.' — the load-bearing premise: row-locality makes the prune EXACT (never approximate), which is what licenses paying the forward only for kept rows. THE DROP CLAUSE (same diff, verbatim): 'A draft the grammar rejects, a stop token, and the rows under either are dropped: the parent's masked row cannot choose the first, and the reply ends at the second, so no accepted path holds them.' BOUNDED REFUSAL SURFACE (commit 98fb8f9 message, verbatim): 'It answers 400 when the engine cannot enforce a schema, xgrammar is missing, the schema does not compile' — and the TP sharing face: 'def follow(...): \"\"\"The constraint another rank ``pack``ed, compiled here: both ranks then walk and mask the same rows.\"\"\"' (grammar.py:157-158) — the two-rank walk is kept coherent by packing the compiled constraint, not by re-deriving it per rank (rank 1 receives the packed bytes only when structured output is on — families/glm5_next/cuda/engine.py:530 'constraint = grammar.compiler(...).follow(packed)' inside 'if packed:'). KINSHIP (do not double-count): prompt-continuation-draft-override-measured-min-match (entries_10, B182) is the SAME window, other half — that OVERRIDES the proposer's draft ids when the prompt continuation is already known; THIS prunes the proposed rows by path-local grammar admissibility before the window is paid, and never changes what an accepted path verifies, only which rows get forward work (they compose: lookup picks better drafts, grammar-window refuses to pay for undraftable ones). Cross-domain color: verify-window-prework-loads-before-stores (kernel_opt, B182) orders loads/stores INSIDE the window's forward; this decides the window's ROW SET before the forward exists. NOVEL: the corpus carries zero grammar/constrained-decoding content (grep: 'grammar' hits only as prose — 'the name grammar' in B193's PlaneForm doc; 'draft trees' as prose in the gpu_08 prompt-lookup rider). Cite: @ c4646171 — engine/grammar.py:273+297+305+321-323+157-158; commit 98fb8f9 (the exactness law + drop clause + refusal surface); Batch 196 / Plan 195.".to_string()),
            // Not benchable: the win is rows-not-paid-for inside a serving
            // verify forward — no Rust-side A/B axis.
            #[cfg(feature = "rust_perf_bench")]
            bench_spec: None,
        },
        // ── allocation (host accounting): a startup capacity plan derives
        // EVERY term from the allocation shapes themselves and proves it
        // with a fake-allocator reconciliation — never a fixed guess ────
        // Source: cuda/geometry.py (exl3_expert_scratch + its consumers),
        // commit 3f35ea9ff3 (the guess → derived correction),
        // tests/test_cuda_geometry.py (the reconciliation).
        PerfRule {
            rule_id: "startup-estimate-derived-from-allocation-shapes".to_string(),
            name: "a startup capacity plan (the admission budget a server gates downloads/boots against) must derive EVERY memory term from the allocation shapes the engine actually allocates — a helper mirroring the allocator's own formula per buffer set, consumed where the plan sums its terms — and prove the derivation with a fake-allocator reconciliation at real shapes (allocated <= estimate, == for a term the helper owns); a fixed per-unit guess lies the moment a representation, a knob, or an uncounted buffer set moves".to_string(),
            category: "allocation".to_string(),
            buggy_code: "const EXL3_TERM_PER_RANK: usize = 1_207_959_552; // 1.125 GiB: a FIXED guess\n\npub struct CapacityPlan {\n    weights_bytes: usize,\n    cache_bytes: usize,\n}\n\nimpl CapacityPlan {\n    // The plan sums one guessed constant for the expert scratch. The\n    // engine actually allocates a Scratch per buffer set (fp16 rotated\n    // inputs + fp32 split-K sums) AND 1 GiB of prompt split-K partials\n    // nothing counted — the estimate reads ~2.5 GiB under, and the\n    // admission gate waves through boots that then fail at runtime.\n    pub fn estimate(&self, _slots: usize, _d: usize, _width: usize) -> usize {\n        self.weights_bytes + self.cache_bytes + EXL3_TERM_PER_RANK\n    }\n}".to_string(),
            fixed_code: "pub struct CapacityPlan {\n    weights_bytes: usize,\n    cache_bytes: usize,\n}\n\n// The term is DERIVED from the allocation shapes — the same formula the\n// allocator uses per buffer set (fp16 rotated inputs: gate/up and down;\n// fp32 split-K sums) — so a representation, a knob, or a buffer-set\n// change moves the estimate with the allocations, not with a stale\n// constant. Reconciliation keeps it honest: a FAKE allocator records\n// every array it hands out at real shapes, and the test asserts\n// allocated <= estimate (== for the term this helper owns).\nfn exl3_expert_scratch(rows: usize, slots: usize, d: usize, width: usize) -> usize {\n    let pairs = rows * slots;\n    2 * pairs * d * 2 + pairs * width * 2 + 2 * 4 * pairs * width.max(d) * 4\n}\n\nimpl CapacityPlan {\n    pub fn estimate(\n        &self,\n        decode: (usize, usize, usize, usize),  // (rows, slots, d, width)\n        prefill: (usize, usize, usize, usize), // the prompt chunk's set\n        prompt_partials_bytes: usize,          // the partials, counted now\n    ) -> usize {\n        let (dr, ds, dd, dw) = decode;\n        let (pr, ps, pd, pw) = prefill;\n        self.weights_bytes\n            + self.cache_bytes\n            + exl3_expert_scratch(dr, ds, dd, dw)\n            + exl3_expert_scratch(pr, ps, pd, pw)\n            + prompt_partials_bytes\n    }\n}\n\n#[test]\nfn fake_allocator_reconciliation() {\n    let mut allocated = 0usize;\n    let mut fake_alloc = |bytes: usize| allocated += bytes; // the allocator's own shape math\n    let (rows, slots, d, width) = (64, 9, 4096, 1024); // real shapes\n    let term = exl3_expert_scratch(rows, slots, d, width);\n    let scratch = fake_alloc(term); // == the helper, per shape\n    assert_eq!(allocated, term);\n    let _ = scratch;\n    let plan = CapacityPlan { weights_bytes: 0, cache_bytes: 0 };\n    let estimate = plan.estimate((rows, slots, d, width), (rows, slots, d, width), 0);\n    assert!(allocated <= estimate); // allocated <= estimate at real shapes\n}".to_string(),
            context_notes: Some("NotBenchable decision-content (the fix IS host accounting; the measured numbers price the harm, not a fixable code shape — the Batch-182 adoption-trial annotation class). SOURCE (TensorFold v0.6.0 @ c4646171, Apache-2.0 — license flipped MIT→Apache-2.0 at 0.6.0; provenance: TensorFold v0.6.0 @ c4646171, Apache-2.0 (license flipped MIT→Apache-2.0 at 0.6.0)). THE CORE CORRECTION (commit 3f35ea9ff3 message, verbatim): 'mla_geometry's EXL3 term was 128 x 64 rows x 9 slots x max(width, hidden) x 4 B (1.125 GiB a rank on GLM-5.3-Flash), a fixed guess.' (provenance: commit-message) and 'The prompt buffers' split-K partials for the BF16 projections (forward.Buffers.sk, 8 x 2,048 x 16,384 fp32 = 1 GiB), which nothing counted.' (commit-message) — the measured correction '+2.52 GiB (no MTP) / +2.60 GiB (MTP head) against the old term, at any window' (commit-message). THE DERIVED TERM (src/tensorfold/cuda/geometry.py:222-226, verbatim): 'def exl3_expert_scratch(rows: int, slots: int, d: int, width: int) -> int: \"\"\"GLM's ``exl3_mm.Scratch`` for ``rows`` x ``slots`` pairs: fp16 rotated inputs and the fp32 split-K sums.\"\"\"' with 'pairs = rows * slots' + 'return 2 * pairs * d * 2 + pairs * width * 2 + 2 * 4 * pairs * max(width, d) * 4' — consumed where the plan sums terms at :255-256 ('fixed += (2 if mtp else 1) * exl3_expert_scratch(rows, slots, d, width)' + 'fixed += exl3_expert_scratch(PREFILL_ROWS, slots, d, width) + 8 * PREFILL_ROWS * 16384 * 4'). THE PROOF IS THE RECONCILIATION (tests/test_cuda_geometry.py:259, verbatim): 'assert bytes_in(arrays) == geometry.exl3_expert_scratch(rows, slots, d, width), rows' — a FAKE exl3_mm.Scratch records every array it hands out at the real shapes (8, 64, 2,048 rows) and the test asserts allocated == the helper per shape and the whole engine's allocations <= the estimate (:269). SUB-ARM (a) ESTIMATOR-BLINDNESS UNDER REPRESENTATION WIDENING (commit 3655360 message, verbatim): 'the admission estimate, which counts file bytes, could not see why' — the NVFP4 widening stored one bf16 pattern a weight + fp32 scales, so a 1.42 GB checkpoint layer held 5.67 GB of tables; the fix carries the checkpoint's own bytes ('the stored bytes are 1.01x the checkpoint's, was 4.00x', commit-message-only) and the estimate form follows ('hold the NVFP4 checkpoint's own bytes and decode them in the kernel', the title). SUB-ARM (b) THE KNOB JOINS THE ESTIMATE AND IS REFUSED PRE-DOWNLOAD (commit f151c6f message + serve_options.py:34-40): '--checkpoint-slots' keeps N prompt states; 'The startup estimate already holds each kept state against the window (stream_geometry), so a larger count leaves a smaller window, and the startup line names it.' and the refusal is PRE-DOWNLOAD ('--checkpoint-slots without --parallel 2 is refused before any download, as is a count below 1' — commit-message; the code: 'if slots < 1: raise ValueError' + the 'if _cuda_streams(...) < 2: raise ValueError(f\"--checkpoint-slots sets the prompt states ...\")' at serve_options.py:36-40). KINSHIP (do not double-count): compaction-reserve-before-prompt-build (entries_07, B141) is the nearest sibling — MEASURED-from-content reserve instead of a guess — but that sizes a RUNTIME buffer from the content it will hold; THIS derives a STARTUP ADMISSION budget from the ALLOCATOR'S OWN allocation shapes and keeps it honest with a fake-allocator reconciliation. lazy-admission-reservation-atomic-register (kernel_opt entries_gpu_63, B195) charges max(actual, estimate) at RUNTIME admission; this fixes the STARTUP estimate the runtime reservation is sized from. GREP DISCLOSURE: 'reconcil' hits the corpus once (kernel_opt mod.rs:1570, pad-skip prose — 'pad-skip reconciles the 256-chunk fill'); 'ALLOCATION SHAPE' hits once (entries_gpu_07, a smem double-buffer layout correction note) — neither carries this mechanism; the corpus has zero startup-estimate/capacity-plan rules. Cite: @ c4646171 — cuda/geometry.py:222-226+255-256; tests/test_cuda_geometry.py:259+269; commit 3f35ea9ff3 (the guess → derived correction + the 2.52/2.60 GiB corrections); commit 3655360 (the NVFP4 sub-arm); commit f151c6f (the knob sub-arm); Batch 196 / Plan 195.".to_string()),
            // Not benchable: the fix IS host accounting — the reconciliation
            // test IS the verification.
            #[cfg(feature = "rust_perf_bench")]
            bench_spec: None,
        },
    ]
}
